def kthKeypadWord(digits, k):
    keys = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl", "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
    k -= 1
    out = []
    for d in reversed(digits):
        letters = keys[d]
        k, idx = divmod(k, len(letters))
        out.append(letters[idx])
    return "".join(reversed(out))
